        ToastAndroid.show("处理时间: " + TotalDecodeTime + "秒, 解码时间： " + decodeTime + "秒", ToastAndroid.LONG);
        ReceiveMultiMessageScreen.message = mergedMessage;

        // 判断文件格式
        let magicNumber = mergedMessagestr.substr(0, 3);
        let saveFile = '';
