  // 计算字符串字节长度
  getBytesSize(str) {
    var cArr = str.match(/[^\x00-\xff]/ig);   
    return str.length + (cArr == null ? 0 : cArr.length*2);    
  }

  // 字符串按字节长度分片实现函数
  reBytesStrArr(str, len, sendType) {
    if (!str || str == undefined) return '';
    let num = 0;
    let result = '';
    let strremainlen = str.length
    for (let i = 0; i < str.length; i++) {
      num += ((str.charCodeAt(i) > 255) ? 3 : 1);
      if (num > len) {
        break;
      } else {
        result = str.substring(0, i + 1);
        strremainlen = i + 1;
      }
    }
    // 2022.01.21 在js层面先转hex
    if (sendType == 'text') {
      hexresult = StrHexUtil.CN2Hex2(result);
    } else if (sendType == 'file') {
      hexresult = StrHexUtil.strToHex(result);
    }
    this.messageSliceArr.push(hexresult);
    
    // 2022.01.21 修复因为split导致的截取错误 
    // 30 * 2
    let nextStr = str.substr(strremainlen);
    this.reBytesStrArr(nextStr, len, sendType);
    return this.messageSliceArr;
  }

  // 进行value的嵌入
  valueEmbed(sessionID, sliceID) {
    leftBits = sessionID.toString(2).padStart(5, '0');  //  将会话id的10进制转为5位2进制表示
    rightBits = sliceID.toString(2).padStart(11, '0');  //  将分片id的10进制转为11位2进制表示
    amountX = parseInt(leftBits + rightBits, 2);    //  从2进制表示转为10进制表示 0-65535
    amountX = amountX / 10**10;
    return amountX;
  }

