  //hbt 获取签名hash
  derawtx2sign = (txRawData, addrs_list) => {
    input_re = [];
    var env = NETWORK_ENV_TESTNET;
    rawTx = BTCTransaction.deserializedfordecode(txRawData, addrs_list, env);
    rawTx.inputs.forEach( input => input.sigHash = [] );
    console.log(rawTx);
    // hbt 参考 BTCTx.js h334  hashInputs
    const hashes = rawTx.inputs.map(input => rawTx.legacyHash(input));
    rawTx.inputs.forEach((input, i) => {
      input.rawSigHash = hashes[i];
    });

    rawTx.inputs.forEach(input => input_re.push(input.rawSigHash));

    return input_re[0];
  } 

