
const StrHexUtil = {
	// 文件字节处理
	hexToStr: function(hex) {
		var hex = hex.toString();
		var str = '';
		for (var i = 0; i < hex.length; i += 2){
			addstr = String.fromCharCode(parseInt(hex.substr(i, 2), 16));
			if (addstr == ''){
				addstr = '\x00';
			} 
			str += addstr;
		}
		return str;
	},
	strToHex: function(str) {
	　　if(str === "")
	　　　　return "";
	　　var hexCharCode = [];
	// 　　hexCharCode.push("0x");
	　　for(var i = 0; i < str.length; i++) {
	　　　　hexCharCode.push((str.charCodeAt(i)).toString(16).padStart(2, '0'));
	　　}
	　　return hexCharCode.join("");
	},


	// 中文文本
	readUTF: function(arr) {
		if (typeof arr === 'string') {
			return arr;
		}
		let UTF = '', _arr = arr;
		for (let i = 0; i < _arr.length; i++) {
			let one = _arr[i].toString(2), v = one.match(/^1+?(?=0)/);
			if (v && one.length == 8) {
				let bytesLength = v[0].length;
				let store = _arr[i].toString(2).slice(7 - bytesLength);
				for (let st = 1; st < bytesLength; st++) {
					store += _arr[st + i].toString(2).slice(2)
				}
				UTF += String.fromCharCode(parseInt(store, 2));
				i += bytesLength - 1
			} else {
				UTF += String.fromCharCode(_arr[i])
			}
		}
		return UTF
	},
	// hexToString
	hex2CN: function (str) {
	  if (str.length % 2 != 0) {
		return console.log('必须为偶数');
	  }
	  let buf = [];
	  for (let i = 0; i < str.length; i += 2) {
		buf.push(parseInt(str.substring(i, i + 2), 16));
	  }
	  return StrHexUtil.readUTF(buf);
	},

	CN2Hex: function (str) {
		let re = /[\u4E00-\u9FA5]/
		let ar = []
		for (let i = 0; i < str.length; i++) {
		  let a = ''
		  if (re.test(str.charAt(i))) { // 中文
			  a = encodeURI(str.charAt(i)).replace(/%/g, '')
		  } else {
			  a = str.charCodeAt(i).toString(16)
		  }
		  ar.push(a)
		}
		str = ar.join('')
		return str
	},	

	
	// 230607 hbt 	
	bytes2hex2: function (bytes){
	let hex="",len=bytes.length;
	for(let i=0;i<len;i++){
		let tmp,num=bytes[i];
		if(num<0){
			tmp=(255+num+1).toString(16);
		}else{
			tmp=num.toString(16);
		}
		if(tmp.length==1){
			return "0"+tmp;
		}
		hex+=tmp;
	}
	return hex
	}, 

	hex2bytes2: function(hex){
	let pos=0,len=hex.length;
	if(len%2!=0){
		return null
	}
	len/2;
	let bytes=new Array();
	for(let i=0;i<len;i++){
		let s=hex.substr(pos,2);
		let v=parseInt(s,16);
		bytes.push(v);
		pos+=2;
	}
	return bytes
	},

	writeUTF2: function (str, isGetBytes=true) {
		var back = [];
		var byteSize = 0;
		for (var i = 0; i < str.length; i++) {
			var code = str.codePointAt(i);
			if (0x00 <= code && code <= 0x7f) {
				byteSize += 1;
				back.push(code);
			} else if (0x80 <= code && code <= 0x7ff) {
				byteSize += 2;
				back.push((192 | (31 & (code >> 6))));
				back.push((128 | (63 & code)))
			} else if ((0x800 <= code && code <= 0xd7ff) 
					|| (0xe000 <= code && code <= 0xffff)) {
				byteSize += 3;
				back.push((224 | (15 & (code >> 12))));
				back.push((128 | (63 & (code >> 6))));
				back.push((128 | (63 & code)))
			}else if((0x10000 <= code && code <= 0x10ffff)){
				byteSize+=4;
			back.push((240 |(7 & (code>>18))))
			back.push((128 |(63 & (code>>12))))
			back.push((128 |(63 & (code>>6))))
			back.push((128 |(63 & (code))))
			}
		}
		for (i = 0; i < back.length; i++) {
			back[i] &= 0xff;
		}
		if (isGetBytes) {
			return back
		}
		if (byteSize <= 0xff) {
			return [0, byteSize].concat(back);
		} else {
			return [byteSize >> 8, byteSize & 0xff].concat(back);
		}
	},

	readUTF2: function (arr) {
	if (typeof arr === 'string') {
		return arr;
	}
	var UTF = '', _arr = arr;
	for (var i = 0; i < _arr.length; i++) {
		var one = _arr[i].toString(2),
				v = one.match(/^1+?(?=0)/);
		if (v && one.length == 8) {
			var bytesLength = v[0].length;
			var store = _arr[i].toString(2).slice(7 - bytesLength);
			for (var st = 1; st < bytesLength; st++) {
				store += _arr[st + i].toString(2).slice(2)
			}
			UTF += String.fromCharCode(parseInt(store, 2));
			i += bytesLength - 1
		} else {
			UTF += String.fromCharCode(_arr[i])
		}
	}
	return UTF
	}, 

	CN2Hex2: function (str){
		return StrHexUtil.bytes2hex2(StrHexUtil.writeUTF2(str))
	},
	Hex2Cn2: function (hex){
		return StrHexUtil.readUTF2(StrHexUtil.hex2bytes2(hex))
	}




	


	
	  
	  
	
}

export default StrHexUtil;
