class BkbTransaction {
  @observable coinType = 0;

  coinID;

  /**
   *
   * @type {string}
   * @memberof Transaction
   */
  @observable hash = undefined;
  @observable inputScript = undefined;
  @observable receivedstamp = undefined;
  @observable txR = undefined;
  @observable txS = undefined;
  @observable txV = undefined;
  @observable amount = undefined;
  @observable NDSamount = undefined;
  @observable fromadr = undefined;
  @observable fees = 0;
  /**
   *
   * @type {number}
   * @memberof Transaction
   */
  @observable timestamp;
    /**
   *
   * @type {number}
   * @memberof Transaction
   */
  @observable amount = 0;

  constructor(obj) {
    this.fees = obj.fees;
    this.hash = obj.hash;
    this.inputScript = obj.inputScript;
    this.timestamp = obj.txCreateTime+'';  
    this.receivedstamp = parseInt((obj.received_stamp+'').slice(0, 10));  // 2022.01.14 yunsle 这里截断前10位 时间戳修复
    this.amount = toFixedString(obj.amount, 18);
    this.NDSamount = toFixedString(obj.amount, 10, true);
    this.txR = obj.r;
    this.txS = obj.s;
    this.txV = obj.v;
    this.txRawtx = obj.rawTx;
    this.fromadr = obj.fromAddress;
  }
}

class BkbTxSet {
  maxtime = 0;
  maxtx = undefined;
  multiMessageFlag = true;
  multiFinishFlag = false;
  SessionID = undefined;
  endsliceid = undefined;
  SliceIDList = [];
  multiComplatedFlag = true;
  HashList = [];

  /**
   *
   *@type {Array.<Transaction>}
  * @memberof TXSet
  */
  @observable allTxs = [];

  constructor(SessionID) {
    this.SessionID = SessionID;
  }

  @observable solopush = (tx) =>{
    // 剔除重复的交易单
    if (!(this.HashList.includes(tx.hash))) {
      this.allTxs.push(tx);
      this.HashList.push(tx.hash);
      if (tx.receivedstamp > this.maxtime) {
        this.maxtx = tx;
        this.maxtime = tx.receivedstamp;
      }
    }
  }
  
  @observable CheckSet = () => {
    this.HashList = [];
    // 是否为单交易单，如果是，则只保留单交易单；
    if(this.maxtx.NDSamount.split('.')[1].slice(0,5) == '00005') {
      this.multiMessageFlag = false;
      this.allTxs = [this.maxtx];
      this.HashList.push(this.maxtx.hash);
      this.multiFinishFlag = true;
    } else{
      // 多交易单
      // 按照时间降序排列
      this.allTxs = this.allTxs.sort(this.sortBy('receivedstamp', -1))
      // 剔除时间超过的交易单，并检查会话完整性
      tmpallTxs = [];
      this.allTxs.forEach( (tmptx) => {
        if (Math.abs(this.maxtime - tmptx.receivedstamp) <= 60*60*12){
          let tmpSplitData = this.valueDecodebtc(tmptx.NDSamount);   
          let tmpSliceID = tmpSplitData[1];
          this.SliceIDList.push(tmpSliceID);
          // if (tmptx.fees == '600') {
          // if (tmptx.fees == '9000'  || tmptx.fees == '600' || tmptx.fees == '25000') {
          let feeint = parseInt(tmptx.fees);
          if (feeint % 4 == TX_BTC_MULTIEND_FEEM4) {
            this.multiFinishFlag = true;
            this.endsliceid = tmpSliceID;
          }
          this.HashList.push(tmptx.hash);
          tmpallTxs.push(tmptx);
        }
      })
      this.allTxs = tmpallTxs;

      if (this.multiFinishFlag) {
        for (let _i=0; _i<this.endsliceid; _i++) {
          if (!(this.SliceIDList.includes(_i))){
            this.multiComplatedFlag = false;
          }
        }
      }else{
        this.multiComplatedFlag = false;
      }
      
    }
  }

  //attr：根据该属性排序；rev：升序1或降序-1，不填则默认为1
  sortBy(attr,rev){
    if( rev==undefined ){ rev=1 }else{ (rev)?1:-1; }
    return function (a,b){
        a=a[attr];
        b=b[attr];
        if(a<b){ return rev*-1}
        if(a>b){ return rev* 1 }
        return 0;
    }
  }

  valueDecodebtc(amount) {
    let embedAmount = amount.split('.')[1].slice(3, 8);
    let embedAmountint = parseInt(embedAmount) - 10000
    let amountBits = embedAmountint.toString(2).padStart(16, '0'); // 将10进制转16位2进制表示
    let leftBits = amountBits.slice(0, 5);
    let rightBits = amountBits.slice(5, 16);
    // 二进制解码为十进制的会话ID和分片ID
    let sessionID = parseInt(leftBits, 2);
    let sliceID = parseInt(rightBits, 2);
    if (embedAmountint < 0){
      return [-1, sliceID];
    } else {
      return [sessionID, sliceID]; 
    }
  }
}

class BkbTxSetDic {
  //  hbt 存储BkbTxSet的字典，用会话号索引；
  SessionCount = 0;
  ComplateSessionCount = 0;
  singleCount = 2;
  SessionIDList = [];
  SingleComplateSessionIDList = [];
  MultiComplateSessionIDList = [];
  SessionIDTimeDic = {};
  SessionIDTimeDic_seslist = [];
  ComplateSessionIDTimeDic = {};
  ComplateSessionIDTimeDic_seslist = [];
  data = {};

  @observable soloadd = (keyobj, txobj) =>{
    // 根据会话进行划分
    if (! this.SessionIDList.includes(keyobj)) {
      this.SessionIDList.push(keyobj);
      this.data[keyobj] = new BkbTxSet(keyobj);
    }
    this.data[keyobj].solopush(txobj);
  }

  // 处理单交易单,将-1的交易单拿出来重新进行插入
  @observable splitSingleSet = () => {
    if (!(typeof this.data[-1] == "undefined")) {
      this.data[-1].allTxs.forEach( (singletx) => {
        if (!(singletx == this.data[-1].maxtx)) {
          let keyobj = 0 - this.singleCount;
          this.singleCount += 1; 
          this.SessionIDList.push(keyobj);
          this.data[keyobj] = new BkbTxSet(keyobj);
          this.data[keyobj].solopush(singletx)
        }
      });
      this.data[-1].allTxs = [this.data[-1].maxtx];
    }    
  }

  // 检查会话个数、完整会话个数，统计完整会话的时间索引降序；
  @observable CheckSetDic = () => {
    this.SessionCount = Object.keys(this.data).length;
    for(tmpkey in this.data){
      console.log(tmpkey);
      this.data[tmpkey].CheckSet();

      this.SessionIDTimeDic[tmpkey] = this.data[tmpkey].maxtime;

      if (this.data[tmpkey].multiComplatedFlag) {
        this.ComplateSessionCount += 1;
        this.ComplateSessionIDTimeDic[tmpkey] = this.data[tmpkey].maxtime;
        if (this.data[tmpkey].multiMessageFlag) {
          this.MultiComplateSessionIDList.push(tmpkey);
        }else{
          this.SingleComplateSessionIDList.push(tmpkey);
        }
      }
    }
    SessionIDTimeDic = this.SessionIDTimeDic;
    this.SessionIDTimeDic_seslist = Object.keys(this.SessionIDTimeDic).sort(function(a,b){ 
      return SessionIDTimeDic[b] - this.SessionIDTimeDic[a]; 
    })
    ComplateSessionIDTimeDic = this.ComplateSessionIDTimeDic;
    this.ComplateSessionIDTimeDic_seslist = Object.keys(this.ComplateSessionIDTimeDic).sort(function(a,b){ 
      return ComplateSessionIDTimeDic[b] - ComplateSessionIDTimeDic[a]; 
    })
  }

  constructor() {}
}

