  isMsgTx = (tx) => {
    let msgtxflag = false;
    if (tx.fees == TX_BTC_SINGLE_FEES1 ||  tx.fees == TX_BTC_SINGLE_FEES2 &&  tx.amount.slice(0,7) == TX_BTC_SINGLE_AMOUNT1) {
      msgtxflag = true;
    }
    if (tx.fees == TX_BTC_MULTING_FEES1 || tx.fees == TX_BTC_MULTIEND_FEES1 || tx.fees == TX_BTC_MULTING_FEES2 || tx.fees == TX_BTC_MULTIEND_FEES2){
      const bignumer = new BigNumber(tx.NDSamount);
      if  (bignumer.isLessThan(new BigNumber(TX_BTC_MULTI_AMOUNT_MAX)) && new BigNumber(TX_BTC_MULTI_AMOUNT_MIN).isLessThan(bignumer)) {
        msgtxflag = true;
      }
    }
    return msgtxflag;
  }

