@observer
class AudioMessageView extends Component {

  @computed get title() {
    return this.props.title;
  }

  playAudio = () => {
    // let whoosh = new Sound( 'file://' + RNFS.DocumentDirectoryPath + '/temp.mp3?' + new Date(), Sound.MAIN_BUNDLE, (error) => {
    let whoosh = new Sound( RNFS.DocumentDirectoryPath + '/temp.mp3', Sound.MAIN_BUNDLE, (error) => {
      if (error) {
        console.log('failed to load the sound', error);
        return;
      }
      // loaded successfully
      console.log('duration in seconds: ' + whoosh.getDuration() + 'number of channels: ' + whoosh.getNumberOfChannels());
    
      // Play the sound with an onEnd callback
      whoosh.play((success) => {
        if (success) {
          console.log('successfully finished playing');
        } else {
          console.log('playback failed due to audio decoding errors');
        }
      });
    });

    // 释放资源
    whoosh.release();

  };
  render() {
    return (
      <View style={alStyles.main}>
        <View style={alStyles.titlec}>
          <Text style={alStyles.title}>{this.title}</Text>
          <View style={alStyles.separator} />
        </View>
        <Button 
          title={"播放"}
          buttonStyle={[alStyles.button]}
          onPress={() => {this.playAudio()}}
        ></Button>
      </View>
    );
  }
}

