export default class MessageSendScreen extends Screen {
  static get screenID() {
    return "MessageSendScreen";
  }

  @observable message = "";

  constructor(props) {
    super(props);
    this.state = {
      isAllowScroll: true,
      isLoading: true,
      page: 1,
      contactList: [],
      activeRowKey: null,
    };

    this.channel_len = {
      "address_tail": 1,
      "value_tail": 18,
      "gas_tail": 11,
      "sig_k": 255
    };

    this.channel_indx = {"1": "address_tail",
                "2": "value_tail",
                "3": "gas_tail",
                "4": "sig_k"};

    this.AddrPool_rece = {
      "1":"0x8e8E3FE305923D0EbfA4Fe4b47e4574b6015E751",
      "2":"0x9a1e3c5db4b5dc95ba92f6bd7a094c969e2ef3bd",
      "3":"0x18cee864b4bbcc10782d269935cf801ccbb8ae9d"
    }

    this.fee =  {
      'ETH':0.0025,
      'BTC':0.0002
    }

    this.props.navigator.addOnNavigatorEvent(this.onNavigatorEvent.bind(this));
  }

  // 导航栏事件
  onNavigatorEvent(event) {
    console.log("联系人事件===>>", event);
    if (event.type == "NavBarButtonPress") {
      if (event.id == "addContact") {
        this.props.navigator.push({
          screen: "AddContactScreen",
          title: i18n.tt(BIZ_SCOPE.mine, "contact-add"),
        });
      }
    } else {
      switch (event.id) {
        case "willAppear":
          break;
        case "didAppear": // pop 回退会触发该事件
          // this.getContactList();
          break;
        case "willDisappear":
          break;
        case "didDisappear":
          break;
        case "willCommitPreview":
          break;
      }
    }
  }

  
  
  
  pack_mess = (message) => {
    return message;
  }

  get_channel_capacity = (channel) => {
    return this.channel_len[this.channel_indx[channel]]
  }

  // 将文本转为UTF8编码  与Python实现保持统一
  // 如"我"转为11100110
  str2utf8 = (str)=> {
    return eval('\''+encodeURI(str).replace(/%/gm, '\\x')+'\'');
  }
  //将字符串转换成二进制形式
  str2bin = (str) => {
    var result = [];
    var list = str.split("");
    // console.log(list);
    for(var i=0;i<list.length;i++){
      var item = list[i];
      if (this.str2utf8(item).length > 1){
        var binaryStr = this.str2utf8(item).charCodeAt().toString(2);
        for(var j=1;j<this.str2utf8(item).length;j++){
          binaryStr += this.str2utf8(item).charCodeAt(j).toString(2);
        }
      } else {
        var binaryStr = this.str2utf8(item).charCodeAt().toString(2);  
        var count = 8 - (binaryStr.length%8);
        if (count != 8){
          var padding = '0'.repeat(count);  
        }
        binaryStr = padding + binaryStr;
      }
      result.push(binaryStr);
    }   
    return result.join("");
  }

  hex2bin = (addr) => {
    addr = addr.slice(2, addr.length)
    var count = addr.length / 2;
    var bitmp = '';
    var addr_bin = '';
    for (var i=0; i < count; i++){
      bitmp += '%'+addr.slice(i * 2, (i + 1) * 2);
    }
    bitmp = eval('\''+bitmp.replace(/%/gm, '\\x')+'\'');
    // console.log(bitmp);

    var byte_len = bitmp.length
    for (var i=0; i < byte_len; i++) {
      var bin_bitmp = bitmp.charCodeAt(i).toString(2);
      if (bin_bitmp.length < 8) {
        var padding = '0'.repeat(8-bin_bitmp.length);
        bin_bitmp = padding + bin_bitmp;
      }
      addr_bin += bin_bitmp;
    }
    return addr_bin
  }

  mes2steg = (mes_bin, chan_indx) =>{
    if (this.channel_indx[chan_indx] == "address_tail") {
      var addrpool_length = Object.keys(this.AddrPool_rece).length;
      for (var i=0; i<addrpool_length;i++) {
        // 先获取好地址池的长度
        var tmp_index = Math.floor(Math.random() * (addrpool_length)) + 1;
        var addr = this.AddrPool_rece[tmp_index]
        // console.log(addr)
        var addr_bin = this.hex2bin(addr)
        var addr_steg = addr_bin.slice(-Number(this.get_channel_capacity(chan_indx)), addr_bin.length)
        if (addr_steg.slice(0,mes_bin.length) == mes_bin) {
          var flag_suc = true
          break
        }
        if (i == addrpool_length-1) {
          var flag_suc = false
        }
      }
      return [addr, flag_suc]
    } else if (this.channel_indx[chan_indx] == "value_tail") {
      // console.log(mes_bin)
      if (this.channel_len["value_tail"] > mes_bin.length) {
          mes_bin += '0'.repeat(this.channel_len["value_tail"] - mes_bin.length)
      }
      var value_steg = parseInt('1' + mes_bin, 2)
      var value = this.fee['ETH'] + value_steg * Math.pow(10, -8)
      value = value.toFixed(8)
      // return [float('{0:.8f}'.format(value)), true]
      // console.log(value)
      return [value, true]
    } else if (this.channel_indx[chan_indx] == "gas_tail") {
      if (this.channel_len["gas_tail"] > mes_bin.length) {
          mes_bin += '0'.repeat(this.channel_len["gas_tail"] - mes_bin.length)
      }
      var gas_steg = parseInt(mes_bin, 2)
      var gas = this.fee['ETH'] + gas_steg * Math.pow(10, -6)
      gas = gas.toFixed(6)
      // console.log(gas)
      // return [float('{0:.6f}'.format(gas)), true]
      return [gas, true]
    } else if (this.channel_indx[chan_indx] == "sig_k") {
      // console.log('length', mes_bin.length);
      var range = this.channel_len["sig_k"] - mes_bin.length;
      if (this.channel_len["sig_k"] > mes_bin.length) {
          for ( i=0; i<(range); i++) {
              mes_bin += Math.round(Math.random())
          }
      }
      // console.log(mes_bin)
      var sig_k = ''+BigInt(parseInt(mes_bin, 2))
      // console.log(sig_k)
      return [sig_k, true]
    }
  }
  
  // 消息处理转换
  mess2stegs = (message, channels) => {
    var mess_bin = this.str2bin(this.pack_mess(message))
    var stegs_dict = {}
    var channs_cap = 0

    console.log(mess_bin)

    for (var channel in channels) {
      // js中这里的循环取值比较奇怪 要+1
      channel = Number(channel) + 1;
      var chann_name = this.channel_indx[channel]
      stegs_dict[chann_name] = []
      channs_cap += this.channel_len[chann_name]
    } 
    console.log('There may need '+ (mess_bin.length / channs_cap) + 1 + 'txs');

    var mes_start = 0
    while (mes_start <= mess_bin.length) {
      for (var chan_indx in channels) {
        // js中这里的循环取值比较奇怪 要+1
        chan_indx = Number(chan_indx) + 1;
        var chan_cap = this.get_channel_capacity(chan_indx);
        // console.log('chan_cap', chan_cap);
        var mes_bin = '';
        if ( (mes_start + chan_cap) > mess_bin.length) {
          mes_bin = mess_bin.slice(mes_start, mess_bin.length)
        } else {
          mes_bin = mess_bin.slice(mes_start, mes_start + chan_cap)
        }
        var temp = this.mes2steg(mes_bin, chan_indx);
        var steg = temp[0];
        var flag_suc = temp[1];
        // console.log(mes_bin, chan_indx, steg, flag_suc);
        stegs_dict[this.channel_indx[chan_indx]].push(steg)
        if (flag_suc) {
          mes_start += chan_cap
        }
      }
    }
    
    console.log(stegs_dict)
    return stegs_dict;
  }


  // 处理发送按钮事件
  sendButtonOnPress = () => {
    this.message = this.message && this.message.trim();
    // alert(this.message);
    // 调用消息处理函数
    // result = this.mess2stegs(this.message, channels=[1,2,3,4]);
    result = this.message;
    // result = Base64Util.encode(this.message);
    // result = StrHexUtil.strToHex(result);
    console.log(result);
    // 调用父页面回调函数 返回结果
    this.props.callback(result)
    this.props.navigator.pop();
  }

  // 渲染
  render() {
    return (
      <View style={styles.container}>

        <View style={styles.card}>
          <View style={[styles.row, styles.border]}>
            <Text style={styles.title}>消息</Text>
          </View>
          <View style={styles.inputWrap}>
            <GrowingTextInput
              underlineColorAndroid="transparent"
              onChangeText={text => (this.message = text)}
              style={styles.input}
              placeholder="必填，要嵌入的消息"
              placeholderTextColor={theme.textColor.placeHolder}
              returnKeyType="done"
              blurOnSubmit={true}
            />
          </View>

          <Footer>
          <Button
            style={styles.button}
            containerStyle={styles.buttonContainer}
            titleStyle={styles.buttonTitle}
            title={i18n.t("common-confirm")}
            onPress={this.sendButtonOnPress}
          />
          </Footer>
        </View>

      </View>
    );
  }
}

